const request = $input.first()?.json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const query = request.query && typeof request.query === 'object' ? request.query : {};
const tenantId = String(headers['x-tenant-id'] ?? headers['X-Tenant-Id'] ?? '').trim();
const runId = String(query.run_id ?? '').trim();
const validRunId = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(runId);
const errors = [];
if (!tenantId) errors.push('x-tenant-id is required');
if (!validRunId) errors.push('run_id must be a UUID');
return [{ json: { valid: errors.length === 0, errors, tenant_id: tenantId, run_id: runId } }];
